               tmp4 = -state%s5(j)
               tmp5 = state%s5(i) + tmp4
               tmp6 = tmp5**(2)
               tmp7 = tmp3 + tmp6
               tmp8 = -state%s6(j)
               tmp9 = state%s6(i) + tmp8
