   !> IEF-PCM (point charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs iefpcm_point_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_response(state, dv, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call iefpcm_point_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[iefpcm_point_response] call iefpcm_point_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_point_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_point_response

   !> One direction of iefpcm_point_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_response_one(state, dv, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c1 => state%s7
      state%op1%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, tmp1, tmp2)
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = dv + tmp3
      tmp5 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp4, tmp5, error)
      if (allocated(error)) return
      tmp6 = state%s15*tmp5
      tmp7 = 0.0_wp
      call state%solver%solve(state%op1, .true., dv, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%s15*tmp7
      tmp9 = tmp6 + tmp8
      tmp10 = state%s17*tmp7
      call gemv(state%s12, tmp10, tmp11, trans="t")
      tmp12 = tmp11*state%a
      hvp_v = tmp9 + tmp12
   end subroutine iefpcm_point_response_one

   !> IEF-PCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs iefpcm_point_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_medium(state, eps, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call iefpcm_point_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[iefpcm_point_complex_medium] call iefpcm_point_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (allocated(state%cx_s25)) deallocate (state%cx_s25)
      if (allocated(state%cx_s26)) deallocate (state%cx_s26)
      if (allocated(state%cx_s27)) deallocate (state%cx_s27)
      if (allocated(state%cx_s28)) deallocate (state%cx_s28)
      if (allocated(state%cx_s29)) deallocate (state%cx_s29)
      if (allocated(state%cx_s30)) deallocate (state%cx_s30)
      if (allocated(state%cx_s31)) deallocate (state%cx_s31)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s25(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s26(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s27(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s28(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s29(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s30(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s31(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_complex_medium] allocation failed")
         return
      end if
      state%cx_s14 = 0.0_wp
      state%cx_s16 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s8 = (-0.15915494309189535_wp)*state%cx_s2
      state%op3%c2 = state%cx_s8
      state%op3%c3 => state%s12
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s3 = -state%cx_s2
      state%cx_s15 = (-0.5_wp)*state%cx_s2
      state%cx_s17 = 0.07957747154594767_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine iefpcm_point_complex_medium

   !> IEF-PCM (point charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs iefpcm_point_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_solve(state, v, energy, q, grad_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp6(:), tmp7(:), tmp14(:), tmp15(:), tmp18(:), &
                               tmp19(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp9(:), tmp10(:), tmp11(:), &
                                  tmp12(:), tmp13(:), tmp16(:), tmp17(:), tmp20(:), tmp21(:), &
                                  tmp22(:), tmp23(:)
      complex(wp) :: tmp8, tmp24

      if (state%matrix_free) then
         call iefpcm_point_complex_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[iefpcm_point_complex_solve] call iefpcm_point_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      state%cx_v = v
      state%cx_s13 = state%a*state%cx_v
      call gemv(state%s12, real(state%cx_s13, wp), tmp2)
      call gemv(state%s12, aimag(state%cx_s13), tmp3)
      tmp1 = cmplx(tmp2, tmp3, wp)
      tmp4 = (-0.15915494309189535_wp)*tmp1
      tmp5 = state%cx_v + tmp4
      call state%solver%solve_complex(state%op3, .false., tmp5, state%cx_s14, error)
      if (allocated(error)) return
      call state%solver%solve_complex(state%op3, .true., state%cx_v, state%cx_s16, error)
      if (allocated(error)) return
      state%cx_s18 = state%cx_s17*state%cx_s16
      call gemv(state%s12, real(state%cx_s18, wp), tmp6, trans="t")
      call gemv(state%s12, aimag(state%cx_s18), tmp7, trans="t")
      state%cx_s19 = cmplx(tmp6, tmp7, wp)
      q = state%cx_s3*state%cx_s14
      tmp8 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp8
      tmp9 = state%cx_s15*state%cx_s14
      tmp10 = state%cx_s15*state%cx_s16
      tmp11 = tmp9 + tmp10
      tmp12 = state%cx_s19*state%a
      grad_v = tmp11 + tmp12
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         call gemv(state%s7, real(state%cx_s14, wp), tmp14)
         call gemv(state%s7, aimag(state%cx_s14), tmp15)
         tmp13 = cmplx(tmp14, tmp15, wp)
         tmp16 = state%a*tmp13
         call gemv(state%s12, real(tmp16, wp), tmp18)
         call gemv(state%s12, aimag(tmp16), tmp19)
         tmp17 = cmplx(tmp18, tmp19, wp)
         tmp20 = state%cx_s8*tmp17
         tmp21 = tmp13 + tmp20
         tmp22 = -tmp21
         tmp23 = tmp5 + tmp22
         tmp24 = sum(tmp10*tmp23)
         energy = energy + tmp24
      end if

      state%cx_ready = 3
   end subroutine iefpcm_point_complex_solve

   !> IEF-PCM (point charges): energy gradient with respect to the other inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs iefpcm_point_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, &
                                           grad_eps, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      complex(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      complex(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      complex(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      complex(wp), contiguous, intent(out) :: grad_a(:)
      !> Partial derivative of the energy with respect to eps
      complex(wp), intent(out) :: grad_eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp4(:), tmp5(:), tmp123(:), tmp124(:)
      real(wp) :: tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, &
                  tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27
      complex(wp), allocatable :: tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp28(:), tmp29(:), &
                                  tmp30(:), tmp31(:), tmp32(:), tmp33(:), tmp116(:), tmp117(:), &
                                  tmp118(:), tmp119(:), tmp120(:), tmp121(:), tmp122(:), tmp127(:)
      complex(wp) :: tmp3, tmp125, tmp126, tmp128, tmp129, tmp130, tmp131, tmp132
      integer :: i, j

      if (state%matrix_free) then
         call iefpcm_point_complex_mf_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, &
                                              grad_eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[iefpcm_point_complex_weights] call iefpcm_point_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[iefpcm_point_complex_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_n) /= [3, npt])) then
         call fatal_error(error, "[iefpcm_point_complex_weights] grad_n: wrong shape")
         return
      end if
      if (any(shape(grad_k1) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_weights] grad_k1: wrong shape")
         return
      end if
      if (any(shape(grad_k2) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_weights] grad_k2: wrong shape")
         return
      end if
      if (any(shape(grad_a) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_weights] grad_a: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp116(npt), stat=stat)
      if (stat == 0) allocate (tmp117(npt), stat=stat)
      if (stat == 0) allocate (tmp118(npt), stat=stat)
      if (stat == 0) allocate (tmp119(npt), stat=stat)
      if (stat == 0) allocate (tmp120(npt), stat=stat)
      if (stat == 0) allocate (tmp121(npt), stat=stat)
      if (stat == 0) allocate (tmp122(npt), stat=stat)
      if (stat == 0) allocate (tmp123(npt), stat=stat)
      if (stat == 0) allocate (tmp124(npt), stat=stat)
      if (stat == 0) allocate (tmp127(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_complex_weights] allocation failed")
         return
      end if
      state%cx_ready = 3

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      call gemv(state%s7, real(state%cx_s14, wp), tmp1)
      call gemv(state%s7, aimag(state%cx_s14), tmp2)
      state%cx_s20 = cmplx(tmp1, tmp2, wp)
      state%cx_s21 = state%a*state%cx_s20
      tmp3 = state%cx_s2**(2)
      state%cx_s22 = (-0.07957747154594767_wp)*tmp3
      state%cx_s23 = state%cx_s22*state%cx_s16
      state%cx_s24 = 0.5_wp*state%cx_s2
      call gemv(state%s12, real(state%cx_s23, wp), tmp4, trans="t")
      call gemv(state%s12, aimag(state%cx_s23), tmp5, trans="t")
      state%cx_s25 = cmplx(tmp4, tmp5, wp)
      tmp6 = state%cx_s24*state%cx_s16
      tmp7 = state%a*state%cx_s25
      state%cx_s26 = tmp6 + tmp7
      tmp8 = state%cx_s18*state%cx_s13
      tmp9 = state%cx_s23*state%cx_s21
      state%cx_s27 = tmp8 + tmp9
      do i = 1, npt
         tmp10 = 1.0_wp/state%a(i)
         tmp11 = 12.566370614359172_wp*tmp10
         tmp12 = sqrt(tmp11)
         tmp13 = (-0.26735_wp)*tmp12
         state%cx_s28(i) = tmp13
      end do
      do i = 1, npt
         tmp14 = 1.0_wp/state%a(i)
         tmp15 = 12.566370614359172_wp*tmp14
         tmp16 = 1.0_wp/sqrt(tmp15)
         tmp17 = state%k1(i) + state%k2(i)
         tmp18 = tmp16*tmp17
         tmp19 = state%a(i)**(-2)
         tmp20 = tmp18*tmp19
         tmp21 = 1.6798095918744622_wp*tmp20
         state%cx_s29(i) = tmp21
      end do
      state%cx_s30 = state%cx_s26*state%cx_s14
      do i = 1, npt
         tmp22 = 1.0_wp/state%a(i)
         tmp23 = 12.566370614359172_wp*tmp22
         tmp24 = 1.0_wp/sqrt(tmp23)
         tmp25 = state%a(i)**(-2)
         tmp26 = tmp24*tmp25
         tmp27 = (-6.719238367497849_wp)*tmp26
         state%cx_s31(i) = tmp27
      end do
      tmp28 = 0.0_wp
      tmp29 = 0.0_wp
      tmp30 = 0.0_wp
      tmp31 = 0.0_wp
      tmp32 = 0.0_wp
      tmp33 = 0.0_wp
      !$omp parallel default(none) &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp31, tmp32, tmp33) &
      !$omp& reduction(+: tmp28, tmp29, tmp30)
      block
         real(wp) :: tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp52, tmp55, tmp59
         complex(wp) :: tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp34, tmp35, tmp36, tmp37, &
                        tmp38, tmp39

         !$omp do schedule(static)
         do j = 1, npt
            tmp40 = state%s9(j)
            tmp41 = state%s4(j)
            tmp42 = state%s5(j)
            tmp43 = state%s10(j)
            tmp44 = state%s6(j)
            tmp45 = state%s11(j)
            tmp46 = state%cx_s13(j)
            tmp47 = state%cx_s18(j)
            tmp48 = state%cx_s21(j)
            tmp49 = state%cx_s23(j)
            tmp50 = state%cx_s14(j)
            tmp51 = state%cx_s26(j)
            tmp52 = -tmp41
            tmp55 = -tmp42
            tmp59 = -tmp44
            tmp34 = 0.0_wp
            tmp35 = 0.0_wp
            tmp36 = 0.0_wp
            tmp37 = 0.0_wp
            tmp38 = 0.0_wp
            tmp39 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp34, tmp35, tmp36, tmp37, tmp38, tmp39)
            do i = 1, j - 1
               block
                  real(wp) :: tmp53, tmp54, tmp56, tmp57, tmp58, tmp60, tmp61, tmp62, tmp63, &
                              tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, &
                              tmp73, tmp74, tmp75, tmp86, tmp87, tmp88, tmp89, tmp90, tmp98, &
                              tmp99, tmp100, tmp101, tmp102
                  complex(wp) :: tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, &
                                 tmp85, tmp91, tmp92, tmp93, tmp94, tmp95, tmp96, tmp97, tmp103, &
                                 tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, tmp110, tmp111, &
                                 tmp112, tmp113, tmp114, tmp115

                  tmp53 = state%s4(i) + tmp52
                  tmp54 = tmp40*tmp53
                  tmp56 = state%s5(i) + tmp55
                  tmp57 = tmp56*tmp43
                  tmp58 = tmp54 + tmp57
                  tmp60 = state%s6(i) + tmp59
                  tmp61 = tmp60*tmp45
                  tmp62 = tmp58 + tmp61
                  tmp63 = tmp62*tmp53
                  tmp64 = tmp53**(2)
                  tmp65 = tmp56**(2)
                  tmp66 = tmp64 + tmp65
                  tmp67 = tmp60**(2)
                  tmp68 = tmp66 + tmp67
                  tmp69 = 1.0_wp/sqrt(tmp68)
                  tmp70 = tmp69**(5)
                  tmp71 = tmp63*tmp70
                  tmp72 = (-3.0_wp)*tmp71
                  tmp73 = tmp69**(3)
                  tmp74 = tmp40*tmp73
                  tmp75 = tmp72 + tmp74
                  tmp76 = tmp46*state%cx_s18(i)
                  tmp77 = tmp48*state%cx_s23(i)
                  tmp78 = tmp76 + tmp77
                  tmp79 = tmp75*tmp78
                  tmp80 = tmp50*state%cx_s26(i)
                  tmp81 = tmp80*tmp73
                  tmp82 = tmp81*tmp53
                  tmp83 = -tmp82
                  tmp84 = tmp79 + tmp83
                  tmp28(i) = tmp28(i) + tmp84
                  tmp85 = -tmp84
                  tmp34 = tmp34 + tmp85
                  tmp86 = tmp56*tmp62
                  tmp87 = tmp86*tmp70
                  tmp88 = (-3.0_wp)*tmp87
                  tmp89 = tmp43*tmp73
                  tmp90 = tmp88 + tmp89
                  tmp91 = tmp90*tmp78
                  tmp92 = tmp50*tmp56
                  tmp93 = tmp92*state%cx_s26(i)
                  tmp94 = tmp93*tmp73
                  tmp95 = -tmp94
                  tmp96 = tmp91 + tmp95
                  tmp29(i) = tmp29(i) + tmp96
                  tmp97 = -tmp96
                  tmp35 = tmp35 + tmp97
                  tmp98 = tmp60*tmp62
                  tmp99 = tmp98*tmp70
                  tmp100 = (-3.0_wp)*tmp99
                  tmp101 = tmp45*tmp73
                  tmp102 = tmp100 + tmp101
                  tmp103 = tmp78*tmp102
                  tmp104 = tmp50*tmp60
                  tmp105 = tmp104*state%cx_s26(i)
                  tmp106 = tmp105*tmp73
                  tmp107 = -tmp106
                  tmp108 = tmp103 + tmp107
                  tmp30(i) = tmp30(i) + tmp108
                  tmp109 = -tmp108
                  tmp36 = tmp36 + tmp109
                  tmp110 = tmp78*tmp73
                  tmp111 = tmp110*tmp53
                  tmp37 = tmp37 + tmp111
                  tmp112 = tmp56*tmp78
                  tmp113 = tmp112*tmp73
                  tmp38 = tmp38 + tmp113
                  tmp114 = tmp60*tmp78
                  tmp115 = tmp114*tmp73
                  tmp39 = tmp39 + tmp115
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp34, tmp35, tmp36, tmp37, tmp38, tmp39)
            do i = j + 1, npt
               block
                  real(wp) :: tmp53, tmp54, tmp56, tmp57, tmp58, tmp60, tmp61, tmp62, tmp63, &
                              tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, &
                              tmp73, tmp74, tmp75, tmp86, tmp87, tmp88, tmp89, tmp90, tmp98, &
                              tmp99, tmp100, tmp101, tmp102
                  complex(wp) :: tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, &
                                 tmp85, tmp91, tmp92, tmp93, tmp94, tmp95, tmp96, tmp97, tmp103, &
                                 tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, tmp110, tmp111, &
                                 tmp112, tmp113, tmp114, tmp115

                  tmp53 = state%s4(i) + tmp52
                  tmp54 = tmp40*tmp53
                  tmp56 = state%s5(i) + tmp55
                  tmp57 = tmp56*tmp43
                  tmp58 = tmp54 + tmp57
                  tmp60 = state%s6(i) + tmp59
                  tmp61 = tmp60*tmp45
                  tmp62 = tmp58 + tmp61
                  tmp63 = tmp62*tmp53
                  tmp64 = tmp53**(2)
                  tmp65 = tmp56**(2)
                  tmp66 = tmp64 + tmp65
                  tmp67 = tmp60**(2)
                  tmp68 = tmp66 + tmp67
                  tmp69 = 1.0_wp/sqrt(tmp68)
                  tmp70 = tmp69**(5)
                  tmp71 = tmp63*tmp70
                  tmp72 = (-3.0_wp)*tmp71
                  tmp73 = tmp69**(3)
                  tmp74 = tmp40*tmp73
                  tmp75 = tmp72 + tmp74
                  tmp76 = tmp46*state%cx_s18(i)
                  tmp77 = tmp48*state%cx_s23(i)
                  tmp78 = tmp76 + tmp77
                  tmp79 = tmp75*tmp78
                  tmp80 = tmp50*state%cx_s26(i)
                  tmp81 = tmp80*tmp73
                  tmp82 = tmp81*tmp53
                  tmp83 = -tmp82
                  tmp84 = tmp79 + tmp83
                  tmp28(i) = tmp28(i) + tmp84
                  tmp85 = -tmp84
                  tmp34 = tmp34 + tmp85
                  tmp86 = tmp56*tmp62
                  tmp87 = tmp86*tmp70
                  tmp88 = (-3.0_wp)*tmp87
                  tmp89 = tmp43*tmp73
                  tmp90 = tmp88 + tmp89
                  tmp91 = tmp90*tmp78
                  tmp92 = tmp50*tmp56
                  tmp93 = tmp92*state%cx_s26(i)
                  tmp94 = tmp93*tmp73
                  tmp95 = -tmp94
                  tmp96 = tmp91 + tmp95
                  tmp29(i) = tmp29(i) + tmp96
                  tmp97 = -tmp96
                  tmp35 = tmp35 + tmp97
                  tmp98 = tmp60*tmp62
                  tmp99 = tmp98*tmp70
                  tmp100 = (-3.0_wp)*tmp99
                  tmp101 = tmp45*tmp73
                  tmp102 = tmp100 + tmp101
                  tmp103 = tmp78*tmp102
                  tmp104 = tmp50*tmp60
                  tmp105 = tmp104*state%cx_s26(i)
                  tmp106 = tmp105*tmp73
                  tmp107 = -tmp106
                  tmp108 = tmp103 + tmp107
                  tmp30(i) = tmp30(i) + tmp108
                  tmp109 = -tmp108
                  tmp36 = tmp36 + tmp109
                  tmp110 = tmp78*tmp73
                  tmp111 = tmp110*tmp53
                  tmp37 = tmp37 + tmp111
                  tmp112 = tmp56*tmp78
                  tmp113 = tmp112*tmp73
                  tmp38 = tmp38 + tmp113
                  tmp114 = tmp60*tmp78
                  tmp115 = tmp114*tmp73
                  tmp39 = tmp39 + tmp115
               end block
            end do
            tmp28(j) = tmp28(j) + tmp34
            tmp29(j) = tmp29(j) + tmp35
            tmp30(j) = tmp30(j) + tmp36
            tmp31(j) = tmp31(j) + tmp37
            tmp32(j) = tmp32(j) + tmp38
            tmp33(j) = tmp33(j) + tmp39
         end do
         !$omp end do
      end block
      !$omp end parallel
      grad_r(1, :) = tmp28
      grad_r(2, :) = tmp29
      grad_r(3, :) = tmp30
      grad_n(1, :) = tmp31
      grad_n(2, :) = tmp32
      grad_n(3, :) = tmp33
      grad_k1 = state%cx_s27*state%cx_s28
      grad_k2 = grad_k1
      tmp116 = state%cx_s19*state%cx_v
      tmp117 = state%cx_s25*state%cx_s20
      tmp118 = tmp116 + tmp117
      tmp119 = state%cx_s27*state%cx_s29
      tmp120 = tmp118 + tmp119
      tmp121 = state%cx_s30*state%cx_s31
      grad_a = tmp120 + tmp121
      call gemv(state%s12, real(state%cx_s21, wp), tmp123)
      call gemv(state%s12, aimag(state%cx_s21), tmp124)
      tmp122 = cmplx(tmp123, tmp124, wp)
      tmp125 = sum(tmp6*tmp122)
      tmp126 = (-0.15915494309189535_wp)*tmp125
      tmp127 = 0.5_wp*state%cx_v
      tmp128 = sum(tmp127*state%cx_s14)
      tmp129 = -tmp128
      tmp130 = tmp126 + tmp129
      tmp131 = state%cx_s1**(-2)
      tmp132 = tmp130*tmp131
      grad_eps = 2.0_wp*tmp132

      state%cx_ready = 4
   end subroutine iefpcm_point_complex_weights

   !> IEF-PCM (point charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs iefpcm_point_complex_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_tangent(state, dr, dn, dk1, dk2, da, dv, hvp_r, hvp_n, hvp_k1, &
                                           hvp_k2, hvp_a, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, r block
      complex(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      complex(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      complex(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      complex(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, a block
      complex(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call iefpcm_point_complex_mf_tangent(state, dr, dn, dk1, dk2, da, dv, hvp_r, hvp_n, &
                                              hvp_k1, hvp_k2, hvp_a, hvp_v, error)
         return
      end if
      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[iefpcm_point_complex_tangent] call iefpcm_point_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_tangent] da: wrong shape")
