         tmp655 = 12.566370614359172_wp*tmp654
         tmp656 = 1.0_wp/sqrt(tmp655)
         tmp657 = state%a(i)**(-2)
         tmp658 = tmp656*tmp657
         tmp659 = tmp658*da(i)
         tmp660 = 1.6798095918744622_wp*tmp659
         tmp653(i) = tmp660
      end do
      tmp661 = state%cx_s27*tmp653
      hvp_k1 = tmp652 + tmp661
      hvp_k2 = hvp_k1
      tmp663 = tmp12*state%cx_s18
      tmp662 = tmp663
      !$omp parallel default(none) &
      !$omp& private(i, j) &
      !$omp& shared(dn, dr, npt, state, tmp662)
      block
         real(wp) :: tmp666, tmp667, tmp668, tmp669, tmp670, tmp671, tmp672, tmp673, tmp674, &
                     tmp675, tmp676, tmp677, tmp678, tmp681, tmp685, tmp688, tmp693, tmp696
         complex(wp) :: tmp665, tmp664

         !$omp do schedule(static)
         do j = 1, npt
            tmp665 = state%cx_s18(j)
            tmp666 = state%s4(j)
            tmp667 = dn(1, j)
            tmp668 = state%s9(j)
            tmp669 = dr(1, j)
            tmp670 = state%s10(j)
            tmp671 = dr(2, j)
            tmp672 = state%s5(j)
            tmp673 = dn(2, j)
            tmp674 = dr(3, j)
            tmp675 = state%s11(j)
            tmp676 = state%s6(j)
            tmp677 = dn(3, j)
            tmp678 = -tmp666
            tmp681 = -tmp669
            tmp685 = -tmp671
            tmp688 = -tmp672
            tmp693 = -tmp674
            tmp696 = -tmp676
            tmp664 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp664)
            do i = 1, j - 1
               block
                  real(wp) :: tmp679, tmp680, tmp682, tmp683, tmp684, tmp686, tmp687, tmp689, &
                              tmp690, tmp691, tmp692, tmp694, tmp695, tmp697, tmp698, tmp699, &
                              tmp700, tmp701, tmp702, tmp703, tmp704, tmp705, tmp706, tmp707, &
                              tmp708, tmp709, tmp710, tmp711, tmp712, tmp713, tmp714, tmp715, &
                              tmp716, tmp717, tmp718, tmp719, tmp720, tmp721, tmp722, tmp723, &
                              tmp724, tmp725, tmp726
                  complex(wp) :: tmp727

                  tmp679 = state%s4(i) + tmp678
                  tmp680 = tmp679*tmp667
                  tmp682 = dr(1, i) + tmp681
                  tmp683 = tmp668*tmp682
                  tmp684 = tmp680 + tmp683
                  tmp686 = dr(2, i) + tmp685
                  tmp687 = tmp670*tmp686
                  tmp689 = state%s5(i) + tmp688
                  tmp690 = tmp689*tmp673
                  tmp691 = tmp687 + tmp690
                  tmp692 = tmp684 + tmp691
                  tmp694 = dr(3, i) + tmp693
                  tmp695 = tmp694*tmp675
                  tmp697 = state%s6(i) + tmp696
                  tmp698 = tmp697*tmp677
                  tmp699 = tmp695 + tmp698
                  tmp700 = tmp692 + tmp699
                  tmp701 = tmp679**(2)
                  tmp702 = tmp689**(2)
                  tmp703 = tmp701 + tmp702
                  tmp704 = tmp697**(2)
                  tmp705 = tmp703 + tmp704
                  tmp706 = 1.0_wp/sqrt(tmp705)
                  tmp707 = tmp706**(3)
                  tmp708 = tmp700*tmp707
                  tmp709 = tmp679*tmp682
                  tmp710 = 2.0_wp*tmp709
                  tmp711 = tmp689*tmp686
                  tmp712 = 2.0_wp*tmp711
                  tmp713 = tmp710 + tmp712
                  tmp714 = tmp697*tmp694
                  tmp715 = 2.0_wp*tmp714
                  tmp716 = tmp713 + tmp715
                  tmp717 = tmp668*tmp679
                  tmp718 = tmp689*tmp670
                  tmp719 = tmp717 + tmp718
                  tmp720 = tmp697*tmp675
                  tmp721 = tmp719 + tmp720
                  tmp722 = tmp716*tmp721
                  tmp723 = tmp706**(5)
                  tmp724 = tmp722*tmp723
                  tmp725 = (-1.5_wp)*tmp724
                  tmp726 = tmp708 + tmp725
                  tmp727 = state%cx_s18(i)*tmp726
                  tmp664 = tmp664 + tmp727
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp664)
            do i = j + 1, npt
               block
                  real(wp) :: tmp679, tmp680, tmp682, tmp683, tmp684, tmp686, tmp687, tmp689, &
                              tmp690, tmp691, tmp692, tmp694, tmp695, tmp697, tmp698, tmp699, &
                              tmp700, tmp701, tmp702, tmp703, tmp704, tmp705, tmp706, tmp707, &
                              tmp708, tmp709, tmp710, tmp711, tmp712, tmp713, tmp714, tmp715, &
                              tmp716, tmp717, tmp718, tmp719, tmp720, tmp721, tmp722, tmp723, &
                              tmp724, tmp725, tmp726
                  complex(wp) :: tmp727

                  tmp679 = state%s4(i) + tmp678
                  tmp680 = tmp679*tmp667
                  tmp682 = dr(1, i) + tmp681
                  tmp683 = tmp668*tmp682
                  tmp684 = tmp680 + tmp683
                  tmp686 = dr(2, i) + tmp685
                  tmp687 = tmp670*tmp686
                  tmp689 = state%s5(i) + tmp688
                  tmp690 = tmp689*tmp673
                  tmp691 = tmp687 + tmp690
                  tmp692 = tmp684 + tmp691
                  tmp694 = dr(3, i) + tmp693
                  tmp695 = tmp694*tmp675
                  tmp697 = state%s6(i) + tmp696
                  tmp698 = tmp697*tmp677
                  tmp699 = tmp695 + tmp698
                  tmp700 = tmp692 + tmp699
                  tmp701 = tmp679**(2)
                  tmp702 = tmp689**(2)
                  tmp703 = tmp701 + tmp702
                  tmp704 = tmp697**(2)
                  tmp705 = tmp703 + tmp704
                  tmp706 = 1.0_wp/sqrt(tmp705)
                  tmp707 = tmp706**(3)
                  tmp708 = tmp700*tmp707
                  tmp709 = tmp679*tmp682
                  tmp710 = 2.0_wp*tmp709
                  tmp711 = tmp689*tmp686
                  tmp712 = 2.0_wp*tmp711
                  tmp713 = tmp710 + tmp712
                  tmp714 = tmp697*tmp694
                  tmp715 = 2.0_wp*tmp714
                  tmp716 = tmp713 + tmp715
                  tmp717 = tmp668*tmp679
                  tmp718 = tmp689*tmp670
                  tmp719 = tmp717 + tmp718
                  tmp720 = tmp697*tmp675
                  tmp721 = tmp719 + tmp720
                  tmp722 = tmp716*tmp721
                  tmp723 = tmp706**(5)
                  tmp724 = tmp722*tmp723
                  tmp725 = (-1.5_wp)*tmp724
                  tmp726 = tmp708 + tmp725
                  tmp727 = state%cx_s18(i)*tmp726
                  tmp664 = tmp664 + tmp727
               end block
            end do
            tmp662(j) = tmp662(j) + tmp664
         end do
         !$omp end do
      end block
      !$omp end parallel
      call gemv(state%s12, real(tmp158, wp), tmp729, trans="t")
      call gemv(state%s12, aimag(tmp158), tmp730, trans="t")
      tmp728 = cmplx(tmp729, tmp730, wp)
      tmp731 = tmp662 + tmp728
      tmp732 = tmp731*state%cx_v
      tmp733 = state%cx_s19*dv
      tmp734 = tmp732 + tmp733
      tmp735 = tmp441*state%cx_s20
      tmp736 = state%cx_s25*tmp317
      tmp737 = tmp735 + tmp736
      tmp738 = tmp734 + tmp737
      tmp739 = tmp651*state%cx_s29
      do i = 1, npt
         tmp741 = state%a(i)**(-2)
         tmp742 = 1.0_wp/state%a(i)
         tmp743 = 12.566370614359172_wp*tmp742
         tmp744 = tmp743**(-1.5_wp)
         tmp745 = state%k1(i) + state%k2(i)
         tmp746 = tmp744*tmp745
         tmp747 = tmp746*tmp741
         tmp748 = tmp747*da(i)
         tmp749 = 6.283185307179586_wp*tmp748
         tmp750 = 1.0_wp/sqrt(tmp743)
         tmp751 = dk1(i) + dk2(i)
         tmp752 = tmp750*tmp751
         tmp753 = tmp749 + tmp752
         tmp754 = tmp741*tmp753
         tmp755 = tmp750*tmp745
         tmp756 = state%a(i)**(-3)
         tmp757 = tmp755*tmp756
         tmp758 = tmp757*da(i)
         tmp759 = (-2.0_wp)*tmp758
         tmp760 = tmp754 + tmp759
         tmp761 = 1.6798095918744622_wp*tmp760
         tmp740(i) = tmp761
      end do
      tmp762 = state%cx_s27*tmp740
      tmp763 = tmp739 + tmp762
      tmp764 = tmp738 + tmp763
      tmp765 = tmp444*state%cx_s14
      tmp766 = state%cx_s26*tmp313
      tmp767 = tmp765 + tmp766
      tmp768 = tmp767*state%cx_s31
      do i = 1, npt
         tmp770 = 1.0_wp/state%a(i)
         tmp771 = 12.566370614359172_wp*tmp770
         tmp772 = tmp771**(-1.5_wp)
         tmp773 = state%a(i)**(-4)
         tmp774 = tmp772*tmp773
         tmp775 = tmp774*da(i)
         tmp776 = 6.283185307179586_wp*tmp775
         tmp777 = 1.0_wp/sqrt(tmp771)
         tmp778 = state%a(i)**(-3)
         tmp779 = tmp777*tmp778
         tmp780 = tmp779*da(i)
         tmp781 = (-2.0_wp)*tmp780
         tmp782 = tmp776 + tmp781
         tmp783 = (-6.719238367497849_wp)*tmp782
         tmp769(i) = tmp783
      end do
      tmp784 = state%cx_s30*tmp769
      tmp785 = tmp768 + tmp784
      hvp_a = tmp764 + tmp785
      tmp786 = state%cx_s15*tmp313
      tmp787 = state%cx_s15*tmp157
      tmp788 = tmp786 + tmp787
      tmp789 = tmp731*state%a
      tmp790 = state%cx_s19*da
      tmp791 = tmp789 + tmp790
      hvp_v = tmp788 + tmp791
   end subroutine iefpcm_point_complex_tangent_one

   !> IEF-PCM (point charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs iefpcm_point_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_response(state, dv, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call iefpcm_point_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[iefpcm_point_complex_response] call iefpcm_point_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_point_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_point_complex_response

   !> One direction of iefpcm_point_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_complex_response_one(state, dv, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp14(:), tmp15(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), &
                                  tmp10(:), tmp11(:), tmp12(:), tmp13(:), tmp16(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_complex_response_one] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, real(tmp1, wp), tmp3)
      call gemv(state%s12, aimag(tmp1), tmp4)
      tmp2 = cmplx(tmp3, tmp4, wp)
      tmp5 = (-0.15915494309189535_wp)*tmp2
      tmp6 = dv + tmp5
      tmp7 = 0.0_wp
      call state%solver%solve_complex(state%op3, .false., tmp6, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%cx_s15*tmp7
      tmp9 = 0.0_wp
      call state%solver%solve_complex(state%op3, .true., dv, tmp9, error)
      if (allocated(error)) return
      tmp10 = state%cx_s15*tmp9
      tmp11 = tmp8 + tmp10
      tmp12 = state%cx_s17*tmp9
      call gemv(state%s12, real(tmp12, wp), tmp14, trans="t")
      call gemv(state%s12, aimag(tmp12), tmp15, trans="t")
      tmp13 = cmplx(tmp14, tmp15, wp)
      tmp16 = tmp13*state%a
      hvp_v = tmp11 + tmp16
   end subroutine iefpcm_point_complex_response_one

   !> IEF-PCM (point charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] k1  first principal curvature (positive where convex)
   !> @param[in] k2  second principal curvature (positive where convex)
   !> @param[in] a  tessera areas, switched (ISWIG: F_i R_I^2 w_i)
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine iefpcm_point_mf_assemble(state, r, n, k1, k2, a, error, solver)
      !> State of iefpcm_point
      type(iefpcm_point_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Tessera areas, switched (ISWIG: F_i R_I^2 w_i)
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] n: wrong shape")
         return
      end if
      if (any(shape(k1) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] k1: wrong shape")
         return
      end if
      if (any(shape(k2) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] k2: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%n)) deallocate (state%n)
      if (allocated(state%k1)) deallocate (state%k1)
      if (allocated(state%k2)) deallocate (state%k2)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s4)) deallocate (state%s4)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s11)) deallocate (state%s11)
      if (allocated(state%s13)) deallocate (state%s13)
      if (allocated(state%s14)) deallocate (state%s14)
      if (allocated(state%s16)) deallocate (state%s16)
      if (allocated(state%s18)) deallocate (state%s18)
      if (allocated(state%s19)) deallocate (state%s19)
      if (allocated(state%s20)) deallocate (state%s20)
      if (allocated(state%s21)) deallocate (state%s21)
      if (allocated(state%s23)) deallocate (state%s23)
      if (allocated(state%s25)) deallocate (state%s25)
      if (allocated(state%s26)) deallocate (state%s26)
      if (allocated(state%s27)) deallocate (state%s27)
      if (allocated(state%s28)) deallocate (state%s28)
      if (allocated(state%s29)) deallocate (state%s29)
      if (allocated(state%s30)) deallocate (state%s30)
      if (allocated(state%s31)) deallocate (state%s31)
      if (allocated(state%s7)) deallocate (state%s7)
      if (allocated(state%s12)) deallocate (state%s12)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%n(3, npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s11(npt), stat=stat)
      if (stat == 0) allocate (state%s13(npt), stat=stat)
      if (stat == 0) allocate (state%s14(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s19(npt), stat=stat)
      if (stat == 0) allocate (state%s20(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s23(npt), stat=stat)
      if (stat == 0) allocate (state%s25(npt), stat=stat)
      if (stat == 0) allocate (state%s26(npt), stat=stat)
      if (stat == 0) allocate (state%s27(npt), stat=stat)
      if (stat == 0) allocate (state%s28(npt), stat=stat)
      if (stat == 0) allocate (state%s29(npt), stat=stat)
      if (stat == 0) allocate (state%s30(npt), stat=stat)
      if (stat == 0) allocate (state%s31(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_mf_assemble] allocation failed")
         return
      end if
      state%s14 = 0.0_wp
      state%s16 = 0.0_wp
      call state%solver%reset(iefpcm_point_n_operators)
      state%matrix_free = .true.

      state%r = r
      state%a = a
      state%n = n
      state%k1 = k1
      state%k2 = k2
      state%s9 = state%n(1, :)
      state%s4 = state%r(1, :)
      state%s5 = state%r(2, :)
      state%s10 = state%n(2, :)
      state%s6 = state%r(3, :)
      state%s11 = state%n(3, :)

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine iefpcm_point_mf_assemble

   !> IEF-PCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs iefpcm_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of iefpcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine iefpcm_point_mf_medium(state, eps, error)
      !> State of iefpcm_point
      type(iefpcm_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[iefpcm_point_mf_medium] call iefpcm_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
