                              tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, &
                              tmp46, tmp47

                  tmp26 = state%s4(i) + tmp25
                  tmp27 = tmp17*tmp26
                  tmp29 = state%s5(i) + tmp28
                  tmp30 = tmp29*tmp20
                  tmp31 = tmp27 + tmp30
                  tmp33 = state%s6(i) + tmp32
                  tmp34 = tmp33*tmp22
                  tmp35 = tmp31 + tmp34
