                                              hvp_k1, hvp_k2, hvp_a, hvp_v, error)
      !> State of iefpcm_point
      type(iefpcm_point_complex_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
