      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, r block
      complex(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      complex(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      complex(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      complex(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, a block
      complex(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[iefpcm_point_complex_mf_tangent] call iefpcm_point_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call iefpcm_point_complex_mf_tangent_one(state, dr(:, :, blk), dn(:, :, blk), &
                                                  dk1(:, blk), dk2(:, blk), da(:, blk), &
                                                  dv(:, blk), hvp_r(:, :, blk), hvp_n(:, :, blk), &
                                                  hvp_k1(:, blk), hvp_k2(:, blk), hvp_a(:, blk), &
                                                  hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine iefpcm_point_complex_mf_tangent

