      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[iefpcm_point_complex_mf_response_one] hvp_v: wrong shape")
         return
