   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine iefpcm_point_op1_apply(self, trans, x, y)
      !> Operator
      class(iefpcm_point_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt)

            call gemv(self%c3, x, tmp1, trans="t")
            tmp2 = self%a*tmp1
            tmp3 = self%c2*tmp2
            tmp4 = x + tmp3
            call gemv(self%c1, tmp4, y, trans="t")
         end block
      else
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt)

            call gemv(self%c1, x, tmp1)
            tmp2 = self%a*tmp1
            call gemv(self%c3, tmp2, tmp3)
            tmp4 = self%c2*tmp3
            y = tmp1 + tmp4
         end block
      end if
   end subroutine iefpcm_point_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine iefpcm_point_op1_assemble(self, a, error)
      !> Operator
      class(iefpcm_point_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op1_assemble] allocation failed")
         return
      end if
      do i = 1, self%npt
         tmp1(:, i) = self%a(i)*self%c3(:, i)
      end do
      call gemm(tmp1, self%c1, tmp2)
      tmp3 = self%c2*tmp2
      a = self%c1 + tmp3
   end subroutine iefpcm_point_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine iefpcm_point_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(iefpcm_point_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[iefpcm_point_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c1(idx, idx)
      tmp3 = self%c3(idx, idx)
      do i = 1, nb
         tmp4(:, i) = tmp1(i)*tmp3(:, i)
      end do
      call gemm(tmp4, tmp2, tmp5)
      tmp6 = self%c2*tmp5
      a = tmp2 + tmp6
   end subroutine iefpcm_point_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine iefpcm_point_op2_apply(self, trans, x, y)
      !> Operator
      class(iefpcm_point_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp9(self%npt), tmp38(self%npt), &
                        tmp39(self%npt), tmp40(self%npt), tmp41(self%npt), tmp42(self%npt), &
                        tmp47(self%npt)
            real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp43, tmp44, tmp45, tmp46
            integer :: i, j

            do i = 1, self%npt
               tmp3 = self%k1(i) + self%k2(i)
               tmp4 = 1.0_wp/self%a(i)
               tmp5 = 12.566370614359172_wp*tmp4
               tmp6 = sqrt(tmp5)
               tmp7 = tmp3*tmp6
               tmp8 = (-0.26735_wp)*tmp7
               tmp2(i) = tmp8
            end do
            tmp9 = tmp2*x
            tmp1 = tmp9
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp1, x)
            block
               real(wp) :: tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp21, tmp25, &
                           tmp10

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp11 = x(j)
                  tmp12 = self%n(1, j)
                  tmp13 = self%r(1, j)
                  tmp14 = self%r(2, j)
                  tmp15 = self%n(2, j)
                  tmp16 = self%r(3, j)
                  tmp17 = self%n(3, j)
                  tmp18 = -tmp13
                  tmp21 = -tmp14
                  tmp25 = -tmp16
                  tmp10 = 0.0_wp
                  !$omp simd &
                  !$omp& reduction(+: tmp10)
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, tmp29, &
                                    tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

                        tmp19 = self%r(1, i) + tmp18
                        tmp20 = tmp12*tmp19
                        tmp22 = self%r(2, i) + tmp21
                        tmp23 = tmp22*tmp15
                        tmp24 = tmp20 + tmp23
                        tmp26 = self%r(3, i) + tmp25
                        tmp27 = tmp26*tmp17
                        tmp28 = tmp24 + tmp27
                        tmp29 = x(i)*tmp28
                        tmp30 = tmp19**(2)
                        tmp31 = tmp22**(2)
                        tmp32 = tmp30 + tmp31
                        tmp33 = tmp26**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = 1.0_wp/sqrt(tmp34)
                        tmp36 = tmp35**(3)
                        tmp37 = tmp29*tmp36
                        tmp10 = tmp10 + tmp37
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp10)
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, tmp29, &
                                    tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37

                        tmp19 = self%r(1, i) + tmp18
                        tmp20 = tmp12*tmp19
                        tmp22 = self%r(2, i) + tmp21
                        tmp23 = tmp22*tmp15
                        tmp24 = tmp20 + tmp23
                        tmp26 = self%r(3, i) + tmp25
                        tmp27 = tmp26*tmp17
                        tmp28 = tmp24 + tmp27
                        tmp29 = x(i)*tmp28
                        tmp30 = tmp19**(2)
                        tmp31 = tmp22**(2)
                        tmp32 = tmp30 + tmp31
                        tmp33 = tmp26**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = 1.0_wp/sqrt(tmp34)
                        tmp36 = tmp35**(3)
                        tmp37 = tmp29*tmp36
                        tmp10 = tmp10 + tmp37
                     end block
                  end do
                  tmp1(j) = tmp1(j) + tmp10
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp38 = self%a*tmp1
            tmp39 = self%c1*tmp38
            tmp40 = x + tmp39
            do i = 1, self%npt
               tmp43 = 1.0_wp/self%a(i)
               tmp44 = 12.566370614359172_wp*tmp43
               tmp45 = sqrt(tmp44)
               tmp46 = 1.0694_wp*tmp45
               tmp42(i) = tmp46
            end do
            tmp47 = tmp42*tmp40
            tmp41 = tmp47
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp40, tmp41)
            block
               real(wp) :: tmp49, tmp50, tmp51, tmp52, tmp53, tmp56, tmp60, tmp48

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp49 = self%r(1, j)
                  tmp50 = self%r(2, j)
                  tmp51 = self%r(3, j)
                  tmp52 = tmp40(j)
                  tmp53 = -tmp49
                  tmp56 = -tmp50
                  tmp60 = -tmp51
                  tmp48 = 0.0_wp
                  !$omp simd &
                  !$omp& reduction(+: tmp48)
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp54, tmp55, tmp57, tmp58, tmp59, tmp61, tmp62, tmp63, tmp64, &
                                    tmp65

                        tmp54 = self%r(1, i) + tmp53
                        tmp55 = tmp54**(2)
                        tmp57 = self%r(2, i) + tmp56
                        tmp58 = tmp57**(2)
                        tmp59 = tmp55 + tmp58
                        tmp61 = self%r(3, i) + tmp60
                        tmp62 = tmp61**(2)
                        tmp63 = tmp59 + tmp62
                        tmp64 = 1.0_wp/sqrt(tmp63)
                        tmp65 = tmp64*tmp40(i)
                        tmp48 = tmp48 + tmp65
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp48)
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp54, tmp55, tmp57, tmp58, tmp59, tmp61, tmp62, tmp63, tmp64, &
                                    tmp65

                        tmp54 = self%r(1, i) + tmp53
                        tmp55 = tmp54**(2)
                        tmp57 = self%r(2, i) + tmp56
                        tmp58 = tmp57**(2)
                        tmp59 = tmp55 + tmp58
                        tmp61 = self%r(3, i) + tmp60
                        tmp62 = tmp61**(2)
                        tmp63 = tmp59 + tmp62
                        tmp64 = 1.0_wp/sqrt(tmp63)
                        tmp65 = tmp64*tmp40(i)
                        tmp48 = tmp48 + tmp65
                     end block
                  end do
                  tmp41(j) = tmp41(j) + tmp48
               end do
               !$omp end do
            end block
            !$omp end parallel
            y = tmp41
         end block
      else
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp7(self%npt), tmp25(self%npt), &
                        tmp26(self%npt), tmp27(self%npt), tmp34(self%npt), tmp62(self%npt)
            real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33
            integer :: i, j

            do i = 1, self%npt
               tmp3 = 1.0_wp/self%a(i)
               tmp4 = 12.566370614359172_wp*tmp3
               tmp5 = sqrt(tmp4)
               tmp6 = 1.0694_wp*tmp5
               tmp2(i) = tmp6
            end do
            tmp7 = tmp2*x
            tmp1 = tmp7
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, x) &
            !$omp& reduction(+: tmp1)
            block
               real(wp) :: tmp8, tmp9, tmp10, tmp11, tmp12, tmp15, tmp19

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp8 = x(j)
                  tmp9 = self%r(1, j)
                  tmp10 = self%r(2, j)
                  tmp11 = self%r(3, j)
                  tmp12 = -tmp9
                  tmp15 = -tmp10
                  tmp19 = -tmp11
                  !$omp simd
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23, &
                                    tmp24

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp8*tmp23
                        tmp1(i) = tmp1(i) + tmp24
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23, &
                                    tmp24

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp8*tmp23
                        tmp1(i) = tmp1(i) + tmp24
                     end block
                  end do
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp25 = self%a*tmp1
            do i = 1, self%npt
               tmp28 = self%k1(i) + self%k2(i)
               tmp29 = 1.0_wp/self%a(i)
               tmp30 = 12.566370614359172_wp*tmp29
               tmp31 = sqrt(tmp30)
               tmp32 = tmp28*tmp31
               tmp33 = (-0.26735_wp)*tmp32
               tmp27(i) = tmp33
            end do
            tmp34 = tmp27*tmp25
            tmp26 = tmp34
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp25) &
            !$omp& reduction(+: tmp26)
            block
               real(wp) :: tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp45, tmp49

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp35 = tmp25(j)
                  tmp36 = self%n(1, j)
                  tmp37 = self%r(1, j)
                  tmp38 = self%r(2, j)
                  tmp39 = self%n(2, j)
                  tmp40 = self%r(3, j)
                  tmp41 = self%n(3, j)
                  tmp42 = -tmp37
                  tmp45 = -tmp38
                  tmp49 = -tmp40
                  !$omp simd
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp43, tmp44, tmp46, tmp47, tmp48, tmp50, tmp51, tmp52, tmp53, &
                                    tmp54, tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61

                        tmp43 = self%r(1, i) + tmp42
                        tmp44 = tmp36*tmp43
                        tmp46 = self%r(2, i) + tmp45
                        tmp47 = tmp46*tmp39
                        tmp48 = tmp44 + tmp47
                        tmp50 = self%r(3, i) + tmp49
                        tmp51 = tmp50*tmp41
                        tmp52 = tmp48 + tmp51
                        tmp53 = tmp35*tmp52
                        tmp54 = tmp43**(2)
                        tmp55 = tmp46**(2)
                        tmp56 = tmp54 + tmp55
                        tmp57 = tmp50**(2)
                        tmp58 = tmp56 + tmp57
                        tmp59 = 1.0_wp/sqrt(tmp58)
                        tmp60 = tmp59**(3)
                        tmp61 = tmp53*tmp60
                        tmp26(i) = tmp26(i) + tmp61
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp43, tmp44, tmp46, tmp47, tmp48, tmp50, tmp51, tmp52, tmp53, &
                                    tmp54, tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61

                        tmp43 = self%r(1, i) + tmp42
                        tmp44 = tmp36*tmp43
                        tmp46 = self%r(2, i) + tmp45
                        tmp47 = tmp46*tmp39
                        tmp48 = tmp44 + tmp47
                        tmp50 = self%r(3, i) + tmp49
                        tmp51 = tmp50*tmp41
                        tmp52 = tmp48 + tmp51
                        tmp53 = tmp35*tmp52
                        tmp54 = tmp43**(2)
                        tmp55 = tmp46**(2)
                        tmp56 = tmp54 + tmp55
                        tmp57 = tmp50**(2)
                        tmp58 = tmp56 + tmp57
                        tmp59 = 1.0_wp/sqrt(tmp58)
                        tmp60 = tmp59**(3)
                        tmp61 = tmp53*tmp60
                        tmp26(i) = tmp26(i) + tmp61
                     end block
                  end do
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp62 = self%c1*tmp26
            y = tmp1 + tmp62
         end block
      end if
   end subroutine iefpcm_point_op2_apply

   !> Form operator 2 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine iefpcm_point_op2_assemble(self, a, error)
      !> Operator
      class(iefpcm_point_op2), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp18(:, :), tmp53(:, :), tmp54(:, :), tmp55(:, :)
      real(wp) :: tmp14, tmp15, tmp16, tmp17, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52
      integer :: i, j

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp18(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp53(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp54(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp55(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op2_assemble] allocation failed")
         return
      end if
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp1)
      do j = 1, self%npt
         block
            real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13

            do i = 1, j - 1
               tmp2 = -self%r(1, j)
               tmp3 = self%r(1, i) + tmp2
               tmp4 = tmp3**(2)
               tmp5 = -self%r(2, j)
               tmp6 = self%r(2, i) + tmp5
               tmp7 = tmp6**(2)
               tmp8 = tmp4 + tmp7
               tmp9 = -self%r(3, j)
               tmp10 = self%r(3, i) + tmp9
               tmp11 = tmp10**(2)
               tmp12 = tmp8 + tmp11
               tmp13 = 1.0_wp/sqrt(tmp12)
               tmp1(i, j) = tmp13
               tmp1(j, i) = tmp13
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp14 = 1.0_wp/self%a(i)
         tmp15 = 12.566370614359172_wp*tmp14
         tmp16 = sqrt(tmp15)
         tmp17 = 1.0694_wp*tmp16
         tmp1(i, i) = tmp17
      end do
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp18)
      do j = 1, self%npt
         block
            real(wp) :: tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, &
                        tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, &
                        tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46

            do i = 1, j - 1
               tmp19 = -self%r(1, j)
               tmp20 = self%r(1, i) + tmp19
               tmp21 = self%n(1, j)*tmp20
               tmp22 = -self%r(2, j)
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*self%n(2, j)
               tmp25 = tmp21 + tmp24
               tmp26 = -self%r(3, j)
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*self%n(3, j)
               tmp29 = tmp25 + tmp28
               tmp30 = tmp20**(2)
               tmp31 = tmp23**(2)
               tmp32 = tmp30 + tmp31
               tmp33 = tmp27**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = 1.0_wp/sqrt(tmp34)
               tmp36 = tmp35**(3)
               tmp37 = tmp29*tmp36
               tmp18(i, j) = tmp37
               tmp38 = -tmp20
               tmp39 = self%n(1, i)*tmp38
               tmp40 = -tmp23
               tmp41 = tmp40*self%n(2, i)
               tmp42 = tmp39 + tmp41
               tmp43 = -tmp27
               tmp44 = tmp43*self%n(3, i)
               tmp45 = tmp42 + tmp44
               tmp46 = tmp45*tmp36
               tmp18(j, i) = tmp46
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp47 = self%k1(i) + self%k2(i)
         tmp48 = 1.0_wp/self%a(i)
         tmp49 = 12.566370614359172_wp*tmp48
         tmp50 = sqrt(tmp49)
         tmp51 = tmp47*tmp50
         tmp52 = (-0.26735_wp)*tmp51
         tmp18(i, i) = tmp52
      end do
      do i = 1, self%npt
         tmp53(:, i) = self%a(i)*tmp18(:, i)
      end do
      call gemm(tmp53, tmp1, tmp54)
      tmp55 = self%c1*tmp54
      a = tmp1 + tmp55
   end subroutine iefpcm_point_op2_assemble

   !> Form operator 2 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine iefpcm_point_op2_assemble_block(self, idx, a, error)
      !> Operator
      class(iefpcm_point_op2), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:)
      real(wp), allocatable :: tmp6(:, :), tmp23(:, :), tmp58(:, :), tmp59(:, :), tmp60(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp19, tmp20, tmp21, tmp22, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[iefpcm_point_op2_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp23(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp58(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp59(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp60(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op2_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp6)
      do j = 1, nb
         block
            real(wp) :: tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, &
                        tmp18

            do i = 1, j - 1
               tmp7 = -tmp1(1, j)
               tmp8 = tmp1(1, i) + tmp7
               tmp9 = tmp8**(2)
               tmp10 = -tmp1(2, j)
               tmp11 = tmp1(2, i) + tmp10
               tmp12 = tmp11**(2)
               tmp13 = tmp9 + tmp12
               tmp14 = -tmp1(3, j)
               tmp15 = tmp1(3, i) + tmp14
               tmp16 = tmp15**(2)
               tmp17 = tmp13 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp6(i, j) = tmp18
               tmp6(j, i) = tmp18
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp19 = 1.0_wp/tmp5(i)
         tmp20 = 12.566370614359172_wp*tmp19
         tmp21 = sqrt(tmp20)
         tmp22 = 1.0694_wp*tmp21
         tmp6(i, i) = tmp22
      end do
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp2, tmp23)
      do j = 1, nb
         block
            real(wp) :: tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, &
                        tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, &
                        tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51

            do i = 1, j - 1
               tmp24 = -tmp1(1, j)
               tmp25 = tmp1(1, i) + tmp24
               tmp26 = tmp2(1, j)*tmp25
               tmp27 = -tmp1(2, j)
               tmp28 = tmp1(2, i) + tmp27
               tmp29 = tmp28*tmp2(2, j)
               tmp30 = tmp26 + tmp29
               tmp31 = -tmp1(3, j)
               tmp32 = tmp1(3, i) + tmp31
               tmp33 = tmp32*tmp2(3, j)
               tmp34 = tmp30 + tmp33
               tmp35 = tmp25**(2)
               tmp36 = tmp28**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = tmp32**(2)
               tmp39 = tmp37 + tmp38
               tmp40 = 1.0_wp/sqrt(tmp39)
               tmp41 = tmp40**(3)
               tmp42 = tmp34*tmp41
               tmp23(i, j) = tmp42
               tmp43 = -tmp25
               tmp44 = tmp2(1, i)*tmp43
               tmp45 = -tmp28
               tmp46 = tmp45*tmp2(2, i)
               tmp47 = tmp44 + tmp46
               tmp48 = -tmp32
               tmp49 = tmp48*tmp2(3, i)
               tmp50 = tmp47 + tmp49
               tmp51 = tmp50*tmp41
               tmp23(j, i) = tmp51
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp52 = tmp3(i) + tmp4(i)
         tmp53 = 1.0_wp/tmp5(i)
         tmp54 = 12.566370614359172_wp*tmp53
         tmp55 = sqrt(tmp54)
         tmp56 = tmp52*tmp55
         tmp57 = (-0.26735_wp)*tmp56
         tmp23(i, i) = tmp57
      end do
      do i = 1, nb
         tmp58(:, i) = tmp5(i)*tmp23(:, i)
      end do
      call gemm(tmp58, tmp6, tmp59)
      tmp60 = self%c1*tmp59
      a = tmp6 + tmp60
   end subroutine iefpcm_point_op2_assemble_block

   !> Apply operator 3 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine iefpcm_point_op3_apply(self, trans, x, y)
      !> Operator
      class(iefpcm_point_op3), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp2(self%npt), tmp3(self%npt), tmp7(self%npt), tmp8(self%npt)
            complex(wp) :: tmp1(self%npt), tmp4(self%npt), tmp5(self%npt), tmp6(self%npt)

            call gemv(self%c3, real(x, wp), tmp2, trans="t")
            call gemv(self%c3, aimag(x), tmp3, trans="t")
            tmp1 = cmplx(tmp2, tmp3, wp)
            tmp4 = self%a*tmp1
            tmp5 = self%c2*tmp4
            tmp6 = x + tmp5
            call gemv(self%c1, real(tmp6, wp), tmp7, trans="t")
            call gemv(self%c1, aimag(tmp6), tmp8, trans="t")
            y = cmplx(tmp7, tmp8, wp)
         end block
      else
         block
            real(wp) :: tmp2(self%npt), tmp3(self%npt), tmp6(self%npt), tmp7(self%npt)
            complex(wp) :: tmp1(self%npt), tmp4(self%npt), tmp5(self%npt), tmp8(self%npt)

            call gemv(self%c1, real(x, wp), tmp2)
            call gemv(self%c1, aimag(x), tmp3)
            tmp1 = cmplx(tmp2, tmp3, wp)
            tmp4 = self%a*tmp1
            call gemv(self%c3, real(tmp4, wp), tmp6)
            call gemv(self%c3, aimag(tmp4), tmp7)
            tmp5 = cmplx(tmp6, tmp7, wp)
            tmp8 = self%c2*tmp5
            y = tmp1 + tmp8
         end block
      end if
   end subroutine iefpcm_point_op3_apply

   !> Form operator 3 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine iefpcm_point_op3_assemble(self, a, error)
      !> Operator
      class(iefpcm_point_op3), intent(in) :: self
      !> Dense operator matrix
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      complex(wp), allocatable :: tmp3(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op3_assemble] allocation failed")
         return
      end if
      do i = 1, self%npt
         tmp1(:, i) = self%a(i)*self%c3(:, i)
      end do
      call gemm(tmp1, self%c1, tmp2)
      tmp3 = self%c2*tmp2
      a = self%c1 + tmp3
   end subroutine iefpcm_point_op3_assemble

   !> Form operator 3 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine iefpcm_point_op3_assemble_block(self, idx, a, error)
      !> Operator
      class(iefpcm_point_op3), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :)
      complex(wp), allocatable :: tmp6(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[iefpcm_point_op3_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op3_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c1(idx, idx)
      tmp3 = self%c3(idx, idx)
      do i = 1, nb
         tmp4(:, i) = tmp1(i)*tmp3(:, i)
      end do
      call gemm(tmp4, tmp2, tmp5)
      tmp6 = self%c2*tmp5
      a = tmp2 + tmp6
   end subroutine iefpcm_point_op3_assemble_block

   !> Apply operator 4 or its transpose (not conjugated)
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine iefpcm_point_op4_apply(self, trans, x, y)
      !> Operator
      class(iefpcm_point_op4), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      complex(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      complex(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp2(self%npt), tmp42(self%npt)
            real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp43, tmp44, tmp45, tmp46
            complex(wp) :: tmp1(self%npt), tmp9(self%npt), tmp38(self%npt), tmp39(self%npt), &
                           tmp40(self%npt), tmp41(self%npt), tmp47(self%npt)
            integer :: i, j

            do i = 1, self%npt
               tmp3 = self%k1(i) + self%k2(i)
               tmp4 = 1.0_wp/self%a(i)
               tmp5 = 12.566370614359172_wp*tmp4
               tmp6 = sqrt(tmp5)
               tmp7 = tmp3*tmp6
               tmp8 = (-0.26735_wp)*tmp7
               tmp2(i) = tmp8
            end do
            tmp9 = tmp2*x
            tmp1 = tmp9
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp1, x)
            block
               real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp21, tmp25
               complex(wp) :: tmp11, tmp10

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp11 = x(j)
                  tmp12 = self%n(1, j)
                  tmp13 = self%r(1, j)
                  tmp14 = self%r(2, j)
                  tmp15 = self%n(2, j)
                  tmp16 = self%r(3, j)
                  tmp17 = self%n(3, j)
                  tmp18 = -tmp13
                  tmp21 = -tmp14
                  tmp25 = -tmp16
                  tmp10 = 0.0_wp
                  !$omp simd &
