                  do i = 1, j - 1
                     block
                        real(wp) :: tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, tmp30, &
                                    tmp31, tmp32, tmp33, tmp34, tmp35, tmp36
                        complex(wp) :: tmp29, tmp37

                        tmp19 = self%r(1, i) + tmp18
                        tmp20 = tmp12*tmp19
                        tmp22 = self%r(2, i) + tmp21
                        tmp23 = tmp22*tmp15
                        tmp24 = tmp20 + tmp23
                        tmp26 = self%r(3, i) + tmp25
                        tmp27 = tmp26*tmp17
                        tmp28 = tmp24 + tmp27
                        tmp29 = x(i)*tmp28
                        tmp30 = tmp19**(2)
                        tmp31 = tmp22**(2)
                        tmp32 = tmp30 + tmp31
                        tmp33 = tmp26**(2)
                        tmp34 = tmp32 + tmp33
                        tmp35 = 1.0_wp/sqrt(tmp34)
                        tmp36 = tmp35**(3)
                        tmp37 = tmp29*tmp36
                        tmp10 = tmp10 + tmp37
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp10)
                  do i = j + 1, self%npt
