                  tmp49 = self%r(1, j)
                  tmp50 = self%r(2, j)
                  tmp51 = self%r(3, j)
                  tmp52 = tmp40(j)
                  tmp53 = -tmp49
                  tmp56 = -tmp50
                  tmp60 = -tmp51
