                        real(wp) :: tmp54, tmp55, tmp57, tmp58, tmp59, tmp61, tmp62, tmp63, tmp64
                        complex(wp) :: tmp65

                        tmp54 = self%r(1, i) + tmp53
                        tmp55 = tmp54**(2)
                        tmp57 = self%r(2, i) + tmp56
                        tmp58 = tmp57**(2)
                        tmp59 = tmp55 + tmp58
                        tmp61 = self%r(3, i) + tmp60
                        tmp62 = tmp61**(2)
                        tmp63 = tmp59 + tmp62
                        tmp64 = 1.0_wp/sqrt(tmp63)
                        tmp65 = tmp64*tmp40(i)
                        tmp48 = tmp48 + tmp65
                     end block
