            end block
            !$omp end parallel
            y = tmp41
         end block
      else
         block
            real(wp) :: tmp2(self%npt), tmp27(self%npt)
            real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33
            complex(wp) :: tmp1(self%npt), tmp7(self%npt), tmp25(self%npt), tmp26(self%npt), &
                           tmp34(self%npt), tmp62(self%npt)
            integer :: i, j

            do i = 1, self%npt
               tmp3 = 1.0_wp/self%a(i)
               tmp4 = 12.566370614359172_wp*tmp3
               tmp5 = sqrt(tmp4)
               tmp6 = 1.0694_wp*tmp5
               tmp2(i) = tmp6
            end do
            tmp7 = tmp2*x
            tmp1 = tmp7
            !$omp parallel default(none) &
            !$omp& private(i, j) &
            !$omp& shared(self, x) &
            !$omp& reduction(+: tmp1)
            block
               real(wp) :: tmp9, tmp10, tmp11, tmp12, tmp15, tmp19
               complex(wp) :: tmp8

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp8 = x(j)
                  tmp9 = self%r(1, j)
                  tmp10 = self%r(2, j)
                  tmp11 = self%r(3, j)
                  tmp12 = -tmp9
                  tmp15 = -tmp10
                  tmp19 = -tmp11
                  !$omp simd
                  do i = 1, j - 1
