                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23
                        complex(wp) :: tmp24

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp8*tmp23
                        tmp1(i) = tmp1(i) + tmp24
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23
                        complex(wp) :: tmp24

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp8*tmp23
                        tmp1(i) = tmp1(i) + tmp24
                     end block
                  end do
               end do
               !$omp end do
            end block
            !$omp end parallel
            tmp25 = self%a*tmp1
            do i = 1, self%npt
               tmp28 = self%k1(i) + self%k2(i)
               tmp29 = 1.0_wp/self%a(i)
               tmp30 = 12.566370614359172_wp*tmp29
               tmp31 = sqrt(tmp30)
               tmp32 = tmp28*tmp31
               tmp33 = (-0.26735_wp)*tmp32
               tmp27(i) = tmp33
            end do
            tmp34 = tmp27*tmp25
            tmp26 = tmp34
            !$omp parallel default(none) &
            !$omp& private(i, j) &
