            !$omp& reduction(+: tmp26)
            block
               real(wp) :: tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp45, tmp49
               complex(wp) :: tmp35

               !$omp do schedule(static)
               do j = 1, self%npt
