                        tmp55 = tmp46**(2)
                        tmp56 = tmp54 + tmp55
                        tmp57 = tmp50**(2)
                        tmp58 = tmp56 + tmp57
                        tmp59 = 1.0_wp/sqrt(tmp58)
                        tmp60 = tmp59**(3)
                        tmp61 = tmp53*tmp60
                        tmp26(i) = tmp26(i) + tmp61
                     end block
                  end do
