                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp43, tmp44, tmp46, tmp47, tmp48, tmp50, tmp51, tmp52, tmp54, &
                                    tmp55, tmp56, tmp57, tmp58, tmp59, tmp60
                        complex(wp) :: tmp53, tmp61

                        tmp43 = self%r(1, i) + tmp42
                        tmp44 = tmp36*tmp43
                        tmp46 = self%r(2, i) + tmp45
                        tmp47 = tmp46*tmp39
                        tmp48 = tmp44 + tmp47
                        tmp50 = self%r(3, i) + tmp49
                        tmp51 = tmp50*tmp41
                        tmp52 = tmp48 + tmp51
                        tmp53 = tmp35*tmp52
                        tmp54 = tmp43**(2)
                        tmp55 = tmp46**(2)
                        tmp56 = tmp54 + tmp55
                        tmp57 = tmp50**(2)
                        tmp58 = tmp56 + tmp57
                        tmp59 = 1.0_wp/sqrt(tmp58)
                        tmp60 = tmp59**(3)
