   end subroutine iefpcm_point_op4_apply

   !> Form operator 4 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine iefpcm_point_op4_assemble(self, a, error)
      !> Operator
      class(iefpcm_point_op4), intent(in) :: self
      !> Dense operator matrix
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp18(:, :), tmp53(:, :), tmp54(:, :)
      real(wp) :: tmp14, tmp15, tmp16, tmp17, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52
      complex(wp), allocatable :: tmp55(:, :)
      integer :: i, j

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp18(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp53(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp54(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp55(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op4_assemble] allocation failed")
         return
      end if
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp1)
      do j = 1, self%npt
         block
            real(wp) :: tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13

            do i = 1, j - 1
               tmp2 = -self%r(1, j)
               tmp3 = self%r(1, i) + tmp2
               tmp4 = tmp3**(2)
               tmp5 = -self%r(2, j)
               tmp6 = self%r(2, i) + tmp5
               tmp7 = tmp6**(2)
               tmp8 = tmp4 + tmp7
               tmp9 = -self%r(3, j)
               tmp10 = self%r(3, i) + tmp9
               tmp11 = tmp10**(2)
               tmp12 = tmp8 + tmp11
               tmp13 = 1.0_wp/sqrt(tmp12)
               tmp1(i, j) = tmp13
               tmp1(j, i) = tmp13
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp14 = 1.0_wp/self%a(i)
         tmp15 = 12.566370614359172_wp*tmp14
         tmp16 = sqrt(tmp15)
         tmp17 = 1.0694_wp*tmp16
         tmp1(i, i) = tmp17
      end do
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(self, tmp18)
      do j = 1, self%npt
         block
            real(wp) :: tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, &
                        tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, &
                        tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46

            do i = 1, j - 1
               tmp19 = -self%r(1, j)
               tmp20 = self%r(1, i) + tmp19
               tmp21 = self%n(1, j)*tmp20
               tmp22 = -self%r(2, j)
               tmp23 = self%r(2, i) + tmp22
               tmp24 = tmp23*self%n(2, j)
               tmp25 = tmp21 + tmp24
               tmp26 = -self%r(3, j)
               tmp27 = self%r(3, i) + tmp26
               tmp28 = tmp27*self%n(3, j)
               tmp29 = tmp25 + tmp28
               tmp30 = tmp20**(2)
               tmp31 = tmp23**(2)
               tmp32 = tmp30 + tmp31
               tmp33 = tmp27**(2)
               tmp34 = tmp32 + tmp33
               tmp35 = 1.0_wp/sqrt(tmp34)
               tmp36 = tmp35**(3)
               tmp37 = tmp29*tmp36
               tmp18(i, j) = tmp37
               tmp38 = -tmp20
               tmp39 = self%n(1, i)*tmp38
               tmp40 = -tmp23
               tmp41 = tmp40*self%n(2, i)
               tmp42 = tmp39 + tmp41
               tmp43 = -tmp27
               tmp44 = tmp43*self%n(3, i)
               tmp45 = tmp42 + tmp44
               tmp46 = tmp45*tmp36
               tmp18(j, i) = tmp46
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, self%npt
         tmp47 = self%k1(i) + self%k2(i)
         tmp48 = 1.0_wp/self%a(i)
         tmp49 = 12.566370614359172_wp*tmp48
         tmp50 = sqrt(tmp49)
         tmp51 = tmp47*tmp50
         tmp52 = (-0.26735_wp)*tmp51
         tmp18(i, i) = tmp52
      end do
      do i = 1, self%npt
         tmp53(:, i) = self%a(i)*tmp18(:, i)
      end do
      call gemm(tmp53, tmp1, tmp54)
      tmp55 = self%c1*tmp54
      a = tmp1 + tmp55
   end subroutine iefpcm_point_op4_assemble

   !> Form operator 4 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine iefpcm_point_op4_assemble_block(self, idx, a, error)
      !> Operator
      class(iefpcm_point_op4), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      complex(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:)
      real(wp), allocatable :: tmp6(:, :), tmp23(:, :), tmp58(:, :), tmp59(:, :)
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :)
      real(wp) :: tmp19, tmp20, tmp21, tmp22, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57
      complex(wp), allocatable :: tmp60(:, :)
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[iefpcm_point_op4_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(3, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp23(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp58(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp59(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp60(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[iefpcm_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%n(:, idx)
      tmp3 = self%k1(idx)
      tmp4 = self%k2(idx)
      tmp5 = self%a(idx)
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp6)
      do j = 1, nb
         block
            real(wp) :: tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, &
                        tmp18

            do i = 1, j - 1
               tmp7 = -tmp1(1, j)
               tmp8 = tmp1(1, i) + tmp7
               tmp9 = tmp8**(2)
               tmp10 = -tmp1(2, j)
               tmp11 = tmp1(2, i) + tmp10
               tmp12 = tmp11**(2)
               tmp13 = tmp9 + tmp12
               tmp14 = -tmp1(3, j)
               tmp15 = tmp1(3, i) + tmp14
               tmp16 = tmp15**(2)
               tmp17 = tmp13 + tmp16
               tmp18 = 1.0_wp/sqrt(tmp17)
               tmp6(i, j) = tmp18
               tmp6(j, i) = tmp18
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp19 = 1.0_wp/tmp5(i)
         tmp20 = 12.566370614359172_wp*tmp19
         tmp21 = sqrt(tmp20)
         tmp22 = 1.0694_wp*tmp21
         tmp6(i, i) = tmp22
      end do
      !$omp parallel do default(none) schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(nb, tmp1, tmp2, tmp23)
      do j = 1, nb
         block
            real(wp) :: tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, &
                        tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, &
                        tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51

            do i = 1, j - 1
               tmp24 = -tmp1(1, j)
               tmp25 = tmp1(1, i) + tmp24
               tmp26 = tmp2(1, j)*tmp25
               tmp27 = -tmp1(2, j)
               tmp28 = tmp1(2, i) + tmp27
               tmp29 = tmp28*tmp2(2, j)
               tmp30 = tmp26 + tmp29
               tmp31 = -tmp1(3, j)
               tmp32 = tmp1(3, i) + tmp31
               tmp33 = tmp32*tmp2(3, j)
               tmp34 = tmp30 + tmp33
               tmp35 = tmp25**(2)
               tmp36 = tmp28**(2)
               tmp37 = tmp35 + tmp36
               tmp38 = tmp32**(2)
               tmp39 = tmp37 + tmp38
               tmp40 = 1.0_wp/sqrt(tmp39)
               tmp41 = tmp40**(3)
               tmp42 = tmp34*tmp41
               tmp23(i, j) = tmp42
               tmp43 = -tmp25
               tmp44 = tmp2(1, i)*tmp43
               tmp45 = -tmp28
               tmp46 = tmp45*tmp2(2, i)
               tmp47 = tmp44 + tmp46
               tmp48 = -tmp32
               tmp49 = tmp48*tmp2(3, i)
               tmp50 = tmp47 + tmp49
               tmp51 = tmp50*tmp41
               tmp23(j, i) = tmp51
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp52 = tmp3(i) + tmp4(i)
         tmp53 = 1.0_wp/tmp5(i)
         tmp54 = 12.566370614359172_wp*tmp53
         tmp55 = sqrt(tmp54)
         tmp56 = tmp52*tmp55
         tmp57 = (-0.26735_wp)*tmp56
         tmp23(i, i) = tmp57
      end do
      do i = 1, nb
         tmp58(:, i) = tmp5(i)*tmp23(:, i)
      end do
      call gemm(tmp58, tmp6, tmp59)
      tmp60 = self%c1*tmp59
      a = tmp6 + tmp60
   end subroutine iefpcm_point_op4_assemble_block

end module moist_model_continuum_component_pcm_kernel_point_iefpcm
